/** Decorative map layer. Keep the same 1400 × 950 coordinate system for overlays. */
export function HotelFloor({ style, className }: { style?: CSSProperties; className?: string }) {
  return (
    <div
      className={className}
      role="img"
      aria-label="Isometric hotel floor plan"
      style={{ position: "absolute", inset: 0, pointerEvents: "none", ...style }}
      dangerouslySetInnerHTML={{ __html: floorSvg }}
    />
  );
}

/** Convert floor-plan units to SVG viewBox coordinates; z lifts objects above the floor. */
export function projectHotelPoint(x: number, y: number, z = 0) {
  return { x: 500 + (x - y) * 0.43, y: 200 + (x + y) * 0.215 - z };
}
